"""Original wavetable / DSP sound generator for the keygen module.

Everything here renders mono 16-bit PCM at SR that is later resampled by the
tracker's note->period mapping, so wavetables are band-limited by design
(Nyquist is computed w.r.t. the *highest* fundamental the table will be asked
to produce within the instrument's range).
"""
import numpy as np

SR = 44100
C8 = 1046.502         # pitch of MIDI note 108 - reference for table design
ATT = 1.0 / (1.0 - np.exp(-1.0))   # normalize one-pole IIR step response


# ---------------------------------------------------------------- helpers
def _snap(v, n):
    """Make v[0]==v[-1] exactly (loop-seam safety) without touching centre."""
    v = np.asarray(v, float).copy()
    a = 0.5 * (v[0] + v[-1])
    v[0] = a
    v[-1] = a
    return v


def env_ad(n, a=0.0, d=1.0, shape=1.0):
    """0->1->0 attack/decay envelope over n samples (shape: pow on decay)."""
    n = int(n)
    if n <= 0:
        return np.zeros(0)
    na = max(1, int(round(n * a)))
    na = min(na, n)
    nd = n - na
    e = np.empty(n)
    if na:
        e[:na] = np.linspace(0.0, 1.0, na, endpoint=False) ** 0.7
    if nd:
        x = np.linspace(1.0, 0.0, nd)
        e[na:] = x ** shape
    return e


def env_adhr(n, a, hold, dec):
    """attack / hold / decay proportions of n."""
    n = int(n)
    na = max(1, int(n * a)); nh = max(0, int(n * hold)); nd = max(1, n - na - nh)
    return np.concatenate([
        (np.linspace(0, 1, na, endpoint=False)) ** 0.7,
        np.ones(nh),
        (np.linspace(1, 0, nd)) ** dec,
    ])


def lowpass(y, k):
    """simple one-pole lowpass, k in (0,1] = coefficient."""
    if k >= 1.0:
        return y
    a = k
    b = 1.0 - a
    out = np.empty_like(y)
    acc = 0.0
    one_pole = np.concatenate(([a], np.zeros(0)))
    # fast path with lfilter-like recursion
    from numpy import convolve  # noqa
    # use cumulative exponential filter via scipy-free recursion
    for i in range(len(y)):
        acc = acc + a * (y[i] - acc)
        out[i] = acc
    return out


def biquad(y, fc, q=0.7071, kind='lp'):
    fc = min(max(fc, 10.0), SR * 0.45)
    w = 2 * np.pi * fc / SR
    cw = np.cos(w); al = np.sin(w) / (2 * q)
    b0 = 1 - cw
    if kind == 'lp':
        b1, b2 = 2 * b0, b0
    elif kind == 'hp':
        b0, b1, b2 = (1 + cw) / 2, -(1 + cw), (1 + cw) / 2
    else:  # peaking-ish bandpass
        b0, b1, b2 = al, 0.0, -al
    a0 = 1 + al; a1 = -2 * cw; a2 = 1 - al
    b0, b1, b2, a1, a2 = b0 / a0, b1 / a0, b2 / a0, a1 / a0, a2 / a0
    x1 = x2 = y1 = y2 = 0.0
    out = np.empty_like(y)
    for i in range(len(y)):
        x = y[i]
        v = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
        x2 = x1; x1 = x; y2 = y1; y1 = v
        out[i] = v
    return out


def resample(wav, cycles, newlen):
    """Linear-interp resample: `wav` is one snapshotted cycle holding `cycles`
    of the fundamental; output length newlen covers the same time span."""
    if newlen <= 0:
        return np.zeros(0)
    span = wav.size / cycles
    pos = np.linspace(0.0, span, int(newlen), endpoint=False)
    i0 = np.floor(pos).astype(np.int64)
    i1 = i0 + 1
    frac = pos - i0
    return _snap(wav[i0] * (1 - frac) + wav[i1] * frac)


def wavetable(harmonic_fn, fmax, nsamp=None):
    """Build one band-limited cycle sampled at fmax (i.e. table = 1/fmax s)."""
    if nsamp is None:
        nsamp = int(round(SR / fmax))
    nsamp = max(16, nsamp)
    nf = max(4, int(fmax))
    fr = np.arange(1, nf + 1, dtype=float)
    amp = np.array([harmonic_fn(k) for k in fr])
    # raised-cosine roll-off at Nyquist
    cut = 0.86
    idx = fr / fmax
    rolloff = np.where(idx < cut, 1.0, 0.5 + 0.5 * np.cos(np.pi * np.clip((idx - cut) / (1 - cut), 0, 1)))
    amp = amp * rolloff
    t = np.arange(nsamp) / nsamp
    y = np.zeros(nsamp)
    for a, k in zip(amp, fr):
        if a != 0:
            y = y + a * np.sin(2 * np.pi * k * t)
    return _snap(y)


def normalize(y, peak=0.9):
    m = np.abs(y).max()
    return y if m < 1e-12 else y * (peak / m)


